import os
import sys


def append_directory_to_paths(filepath):
    current_dir = os.path.dirname(os.path.abspath(filepath))
    sys.path.append(current_dir)


def import_itertools_zip_longest():
    try:
        from itertools import izip_longest

        return izip_longest
    except ImportError:
        from itertools import zip_longest

        return zip_longest


def import_urllib():
    try:
        from urllib import urlopen, URLopener

        return urlopen, URLopener
    except ImportError:
        from urllib.request import urlopen, URLopener

        return urlopen, URLopener


def import_string_io():
    try:
        import StringIO

        return StringIO.StringIO
    except ImportError:
        import io

        return io.StringIO
